    public class MenuEntryBuilder
    {
        public string name;
        public string url;
        public string pageRef;
        public string title;
        public int weight;
        public string parent;
        public string identifier;
        public string pre;
        public string post;
        public string menu;
        public Tsonic.CSharp.Js.Map<string, ParamValue> @params;
        public MenuEntryBuilder(string menu)
        {
            this.name = "";
            this.url = "";
            this.pageRef = "";
            this.title = "";
            this.weight = 0;
            this.parent = "";
            this.identifier = "";
            this.pre = "";
            this.post = "";
            this.menu = menu;
            this.@params = new Tsonic.CSharp.Js.Map<string, ParamValue>();
        }
        public MenuEntry toEntry()
        {
            return new MenuEntry(this.name, this.url, this.pageRef, this.title, this.weight, this.parent, this.identifier, this.pre, this.post, this.menu, this.@params);
        }
    }
    public class LanguageConfigBuilder
    {
        public string lang;
        public string languageName;
        public string languageDirection;
        public string contentDir;
        public int weight;
        public LanguageConfigBuilder(string lang, LanguageConfig? source = null)
        {
            this.lang = lang;
            this.languageName = source?.languageName ?? lang;
            this.languageDirection = source?.languageDirection ?? "ltr";
            this.contentDir = source?.contentDir ?? $"content.{lang}";
            this.weight = source?.weight ?? 0;
        }
        public LanguageConfig toConfig()
        {
            return new LanguageConfig(this.lang, this.languageName, this.languageDirection, this.contentDir, this.weight);
        }
    }
